(function bootcampRuntime(){
let activeLab=0;window.getActiveLab=()=>activeLab;
const safe=s=>escapeHTML(s);
const getLab=(id,i)=>BOOTCAMP_LABS.find(x=>x.id===`${id}-${i}`);
function labHTML(lab){
return `<section class="panel" style="margin-top:15px"><div class="eyebrow">GUIDED LAB · ${activeLab+1} OF 5</div><h2>${safe(lab.name)}</h2><p class="muted">Follow these steps in order. Keep your code, test output, and screenshots as evidence.</p><ol class="labsteps">${lab.steps.map((st,i)=>`<li><b>Step ${i+1}</b><p>${safe(st)}</p></li>`).join("")}</ol><div class="progress-panel"><b>Starting point / command</b><pre class="labcode">${safe(lab.command)}</pre></div><div class="progress-panel" style="margin-top:12px"><b>Definition of done</b><p>${safe(lab.done)}</p><p class="muted small">The task counts only when you can demonstrate the result.</p></div><div class="progress-panel" style="margin-top:12px"><div class="eyebrow">🎯 WHAT YOUR FINISHED RESULT SHOULD LOOK LIKE</div><p>${safe(lab.expected)}</p><p class="small muted"><b>How to verify:</b> ${safe(lab.verify)}</p></div><div class="progress-panel" style="margin-top:12px"><b>🛠 If you get stuck</b><p class="small muted">${safe(lab.troubleshoot)}</p></div><div class="panel" style="margin-top:12px"><h3>📚 Resources for this specific lab</h3><p class="small muted">Read what you need, then return to the exercise. These links lead to documentation, courses, and reference guides.</p>${lab.resources.map(x=>`<a href="${x.url}" target="_blank" rel="noopener noreferrer">${safe(x.label)} ↗</a>`).join("")}</div><div class="panel" style="margin-top:12px"><h3>⌨ Starter code / project scaffold</h3><p class="small muted">Use the template as your starting point. Complete the TODOs yourself.</p><pre class="labcode">${safe(lab.starter)}</pre>${lab.autotest?'<a href="https://github.com/BryanRoubos/ai-architect-quest/tree/main/starter" target="_blank" rel="noopener noreferrer">Open complete runnable starter project ↗</a>':''}</div><div class="progress-panel" style="margin-top:12px"><b>🖥 Example terminal result (target, not a real run)</b><pre class="labcode">${safe(lab.output)}</pre></div><div class="panel" style="margin-top:12px"><h3>🧠 Quick knowledge check</h3><p class="small">${safe(lab.question)}</p><div class="practice-options">${lab.choices.map((c,i)=>`<button type="button" class="practice-choice" data-answer="${i}" data-labid="${lab.id}">${safe(c)}</button>`).join('')}</div><p id="practice-result" class="muted small" aria-live="polite">Choose an answer to receive instant feedback.</p></div>${lab.autotest?'<div class="panel" style="margin-top:12px"><h3>✅ Real automated assessment</h3><p class="muted small">Clone this repository, then run <code>cd starter</code> and <code>python -m pytest -q</code>. The smoke tests pass with the starter code; the assignment tests initially fail and become green as you implement the requirements. GitHub Actions runs the tests on pushes.</p><a href="https://github.com/BryanRoubos/ai-architect-quest/actions/workflows/starter-tests.yml" target="_blank" rel="noopener noreferrer">View automated grading runs ↗</a></div>':''}<label class="quest"><input type="checkbox" data-quest="${lab.id}" ${s.done[lab.id]?"checked":""}><span><b>Lab completed · 40 XP</b><small>I followed all steps and saved the evidence.</small></span></label></section>`;
}
detail=function(){
const l=L[current-1], lab=getLab(current,activeLab);
return `<button class="btn alt" data-nav="roadmap">← All levels</button><div style="margin-top:23px"><div class="eyebrow">AI ARCHITECT BOOTCAMP · LEVEL ${l.id} · WEEKS ${l.weeks[0]}–${l.weeks[1]}</div><h1 style="font-size:clamp(30px,4vw,50px)">${l.icon} ${safe(l.name)}</h1><p class="muted">${safe(l.subtitle)}</p></div><div class="flex"><span class="pill">${count(l)} / 5 guided labs complete</span><span class="pill">${s.boss[l.id]?"Boss defeated":"Boss pending"}</span></div><div class="bar" style="margin:20px 0"><span style="width:${count(l)*20}%"></span></div><div class="columns"><div><div class="panel"><h3>🧪 Lab selection</h3><p class="muted small">Choose a lab to see exactly what to do.</p><div class="lablist">${l.tasks.map((_,i)=>{const x=getLab(current,i);return `<button type="button" class="labtab ${activeLab===i?"selected":""}" data-lab="${i}"><span>${s.done[x.id]?"✓":`0${i+1}`}</span><div><b>${safe(x.name)}</b><small>${safe(l.tasks[i])}</small></div><span>→</span></button>`}).join("")}</div></div>${labHTML(lab)}<section class="boss" style="margin-top:15px"><div class="eyebrow" style="color:#ffd391">⚔ LEVEL BOSS · 100 XP</div><h3>Show what you built</h3><p>${safe(l.boss)}</p><p class="small">Evidence: repository link, reproducible instructions, passing checks, and a 2-minute explanation of your architectural decisions.</p><label class="quest"><input type="checkbox" data-boss="${l.id}" ${s.boss[l.id]?"checked":""}><span><b>Capstone demonstrated</b></span></label></section></div><div class="stack"><div class="panel"><h3>📝 Engineer's notebook</h3><p class="muted small">Keep your commands, test outputs, decisions, and unresolved questions.</p><textarea id="notes" placeholder="Commands, errors, architecture decisions...">${safe(s.notes[l.id]||"")}</textarea><button class="btn alt" id="saveNotes">Save notes</button></div><div class="panel"><h3>📖 Learning references</h3><a href="${l.url}" target="_blank" rel="noopener noreferrer">Primary topic documentation ↗</a><a href="https://roadmap.sh/software-architect" target="_blank" rel="noopener noreferrer">Software architecture roadmap ↗</a></div><div class="progress-panel"><b>Architect's checklist</b><p class="muted small">What fails? What does it cost? What would change at 10× scale? How do you secure it?</p></div></div></div>`;
};
const oldGo=go;
go=function(id){activeLab=0;oldGo(id)};
document.addEventListener("click",e=>{const b=e.target.closest("[data-lab]");if(b){activeLab=Number(b.dataset.lab);render()}const answer=e.target.closest("[data-answer]");if(answer){const lab=BOOTCAMP_LABS.find(x=>x.id===answer.dataset.labid);const correct=Number(answer.dataset.answer)===lab.answer;document.querySelectorAll(".practice-choice").forEach(x=>{x.disabled=true;x.classList.toggle("correct",Number(x.dataset.answer)===lab.answer);x.classList.toggle("wrong",x===answer&&!correct)});const result=document.querySelector("#practice-result");if(result)result.textContent=correct?"✓ Correct. You understand this check.":"Not quite. Review the lab steps, then reopen the lesson to try again."}});
render();
})();